Speaks the documented contract: everything under the /api base path, HTTP
basic authentication sent preemptively on every request, HAL collection
bodies ({records, num_records, _links}) with pagination via _links.next,
and the {error: {code, message, target}} body on failed calls.
"""

import base64
import json
import urllib.error
import urllib.parse
import urllib.request

from .errors import OntapApiError, ResolutionError


class OntapClient:
    def __init__(self, base_url, username, password):
        self.base_url = base_url.rstrip("/")
        token = base64.b64encode(("%s:%s" % (username, password)).encode("utf-8"))
        self._auth_header = "Basic " + token.decode("ascii")

    def request(self, method, path, query=None, body=None):
        """Issue one request and return the decoded JSON document (or None).

        ``path`` is used verbatim when ``query`` is None, so callers may pass
        a server-provided href that already carries its own query string.
        """
        url = self.base_url + path
        if query:
            url += "?" + urllib.parse.urlencode(query)
        data = None
        headers = {
            "Authorization": self._auth_header,
            "Accept": "application/hal+json",
        }
        if body is not None:
            data = json.dumps(body).encode("utf-8")
            headers["Content-Type"] = "application/json"
        req = urllib.request.Request(url, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req) as resp:
                payload = resp.read()
        except urllib.error.HTTPError as exc:
            raise self._decode_http_error(exc) from None
        if not payload:
            return None
        return json.loads(payload.decode("utf-8"))

    @staticmethod
    def _decode_http_error(exc):
        code = message = target = None
        try:
            doc = json.loads(exc.read().decode("utf-8"))
            error = doc.get("error") or {}
            code = error.get("code")
            message = error.get("message")
            target = error.get("target")
        except (ValueError, AttributeError):
            pass
        if message is None:
            message = "HTTP %s" % exc.code
        return OntapApiError(exc.code, code=code, message=message, target=target)

    def get(self, path, query=None):
        return self.request("GET", path, query=query)

    def get_collection(self, path, query):
        """Fetch every record of a collection, following _links.next.

        Collection pages can be partial (return_timeout / max_records) and a
        next link may be present even when no further records exist, so the
        walk stops only when no next link is returned. Once two records have
        been gathered the cardinality questions our callers ask are settled,
        so the walk stops early.
        """
        records = []
        doc = self.get(path, query=query)
        seen_hrefs = set()
        while True:
            records.extend((doc or {}).get("records") or [])
            next_href = (((doc or {}).get("_links") or {}).get("next") or {}).get("href")
            if not next_href or len(records) >= 2 or next_href in seen_hrefs:
                return records
            seen_hrefs.add(next_href)
            doc = self.get(next_href)

    def _resolve_uuid(self, path, name, kind):
        records = self.get_collection(path, {"name": name, "fields": "uuid,name"})
        if len(records) != 1:
            raise ResolutionError(
                "%s '%s' resolved to %d records; exactly one required"
                % (kind, name, len(records))
            )
        return records[0]["uuid"]

    def resolve_svm(self, name):
        return self._resolve_uuid("/api/svm/svms", name, "SVM")

    def resolve_aggregate(self, name):
        return self._resolve_uuid("/api/storage/aggregates", name, "aggregate")

    def find_volume(self, svm_name, name):
        """Return the matching volume record, or None when it does not exist.

        More than one match means the name is ambiguous within the SVM and is
        an error rather than a candidate for reuse.
        """
        records = self.get_collection(
            "/api/storage/volumes",
            {"name": name, "svm.name": svm_name, "fields": "uuid,name,size,state"},
        )
        if not records:
            return None
        if len(records) > 1:
            raise ResolutionError(
                "volume '%s' on SVM '%s' resolved to %d records; at most one expected"
                % (name, svm_name, len(records))
            )
        return records[0]
