[tool_call Write] {"file_path":"ontapvol/jobs.py","content":""""Asynchronous job polling for 202-accepted ONTAP operations.

A job is polled on exactly the href the server returned in
job._links.self.href — never rebuilt from the uuid — until it reaches a
terminal state. The pinned contract and the current job reference name the
failed terminal state "failure"; the current getting-started page spells it
"error", so both spellings are treated as failure.
"""

from .errors import JobFailedError

FAILURE_STATES = frozenset({"failure", "error"})


def poll_job(client, href, sleep, max_polls):
    """Poll the job at ``href`` until success, raising on failure.

    ``sleep`` is the injected pacing callable, invoked as sleep(1.0) before
    every poll except the first. ``max_polls`` bounds the total polls; an
    exhausted budget raises JobFailedError naming the bound.
    """
    for attempt in range(max_polls):
        if attempt:
            sleep(1.0)
        job = client.get(href) or {}
        state = job.get("state")
        if state == "success":
            return job
        if state in FAILURE_STATES:
            error = job.get("error") or {}
            raise JobFailedError(
                error.get("message") or job.get("message") or "job failed",
                code=error.get("code"),
            )
    raise JobFailedError(
        "job did not reach a terminal state within the poll budget of %d polls"
        % max_polls
    )
