from dataclasses import dataclass, field

from .errors import ResolutionError
from .jobs import poll_job


@dataclass
class ProvisionSpec:
    name: str
    svm: str
    aggregates: list
    size: int
    junction_path: str = None


class VolumeProvisioner:
    def __init__(self, client, sleep, max_polls):
        self.client = client
        self.sleep = sleep
        self.max_polls = max_polls

    def provision(self, spec):
        """Provision the volume, reusing it by UUID when it already exists.

        Returns {"uuid", "name", "created", "state"}. The lookup runs before
        any write; on a hit nothing is created and created is False.
        """
        existing = self.client.find_volume(spec.svm, spec.name)
        if existing is not None:
            return self._result(existing, created=False)

        svm_uuid = self.client.resolve_svm(spec.svm)
        aggregate_uuids = [self.client.resolve_aggregate(a) for a in spec.aggregates]

        body = {
            "name": spec.name,
            "svm": {"uuid": svm_uuid},
            "aggregates": [{"uuid": u} for u in aggregate_uuids],
            "size": spec.size,
        }
        if spec.junction_path is not None:
            body["nas"] = {"path": spec.junction_path}

        response = self.client.request(
            "POST", "/api/storage/volumes", query={"return_timeout": "0"}, body=body
        )
        href = response["job"]["_links"]["self"]["href"]
        poll_job(self.client, href, self.sleep, self.max_polls)

        record = self.client.find_volume(spec.svm, spec.name)
        if record is None:
            raise ResolutionError(
                "volume '%s' not found on SVM '%s' after successful create job"
                % (spec.name, spec.svm)
            )
        return self._result(record, created=True)

    @staticmethod
    def _result(record, created):
        return {
            "uuid": record["uuid"],
            "name": record["name"],
            "created": created,
            "state": record.get("state"),
        }
"}

